### Pattern Description

The Tenant-Scoped Configuration Extension pattern integrates extension configuration into the platform's configuration hierarchy with validation, secrets management, and audit capabilities.

**1. Extension Configuration Schema Registration**

Extensions declare their configuration schema using JSON Schema:

```csharp
public class FloridaPriorAuthExtension : IExtension, IExtensionConfiguration
{
    public string GetConfigurationSchema()
    {
        return @"
        {
          "$schema": "http://json-schema.org/draft-07/schema#",
          "type": "object",
          "properties": {
            "apiEndpoint": {
              "type": "string",
              "format": "uri",
              "description": "Florida MMIS API endpoint"
            },
            "timeoutSeconds": {
              "type": "integer",
              "minimum": 1,
              "maximum": 300,
              "default": 30
            },
            "enableCaching": {
              "type": "boolean",
              "default": true
            },
            "serviceCodes": {
              "type": "array",
              "items": { "type": "string" },
              "minItems": 1
            }
          },
          "required": ["apiEndpoint", "serviceCodes"],
          "additionalProperties": false
        }";
    }

    public IEnumerable<string> GetSecretPaths()
    {
        // Declare which config values are secrets
        return new[] { "apiKey", "clientSecret" };
    }
}
```

**2. Configuration Namespace Isolation**

Extension configuration is namespaced to prevent collisions:

```
Configuration Hierarchy:
  /GlobalSettings
    /Timeouts
      RequestTimeout: 30000
  /TenantSettings/{tenantId}
    /Core
      /ClaimsProcessing
        MaxRetries: 3
    /Extensions/{extensionId}      ← Extension configuration namespaced here
      /fl-prior-auth
        apiEndpoint: "https://..."
        timeoutSeconds: 45
        enableCaching: true
        serviceCodes: [...]
```

**3. Configuration Storage Abstraction**

Extensions access configuration through abstraction layer:

```csharp
public interface IExtensionConfigurationProvider
{
    Task<T> GetConfigurationAsync<T>(string tenantId, string extensionId)
        where T : class, new();
    Task SetConfigurationAsync<T>(string tenantId, string extensionId, T configuration)
        where T : class;
    Task<bool> ValidateConfigurationAsync(string extensionId, object configuration);
}

// Extension usage
public async Task InitializeAsync(IExtensionContext context)
{
    var config = await context.Configuration
        .GetConfigurationAsync<FloridaPriorAuthConfig>(
            context.TenantId,
            this.Id);

    _apiEndpoint = config.ApiEndpoint;
    _timeout = TimeSpan.FromSeconds(config.TimeoutSeconds);
}
```

**4. Schema Validation on Registration and Updates**

Configuration validated against schema before persistence:

```csharp
public class ExtensionConfigurationValidator
{
    private readonly Dictionary<string, JsonSchema> _schemas = new();

    public void RegisterSchema(string extensionId, string jsonSchema)
    {
        var schema = JsonSchema.FromText(jsonSchema);
        _schemas[extensionId] = schema;
    }

    public async Task<ValidationResult> ValidateAsync(
        string extensionId,
        object configuration)
    {
        if (!_schemas.TryGetValue(extensionId, out var schema))
        {
            throw new InvalidOperationException(
                $"No schema registered for extension {extensionId}");
        }

        var json = JsonSerializer.Serialize(configuration);
        var validationResult = schema.Validate(json);

        if (!validationResult.IsValid)
        {
            return ValidationResult.Failure(
                validationResult.Errors.Select(e => e.Message));
        }

        return ValidationResult.Success();
    }
}
```

**5. Secrets Management Integration**

Secrets stored in Azure Key Vault, referenced in configuration:

```csharp
public class ExtensionConfigurationProvider : IExtensionConfigurationProvider
{
    private readonly ISecretManager _secretManager;
    private readonly IConfigurationStore _configStore;

    public async Task<T> GetConfigurationAsync<T>(
        string tenantId,
        string extensionId) where T : class, new()
    {
        var configData = await _configStore.GetAsync(tenantId, extensionId);
        var config = JsonSerializer.Deserialize<T>(configData);

        // Resolve secret references
        var secretPaths = GetSecretProperties<T>();
        foreach (var path in secretPaths)
        {
            var secretReference = GetPropertyValue(config, path) as string;
            if (secretReference?.StartsWith("secret://") == true)
            {
                var secretName = secretReference.Substring(9);
                var secretValue = await _secretManager.GetSecretAsync(secretName);
                SetPropertyValue(config, path, secretValue);
            }
        }

        return config;
    }

    public async Task SetConfigurationAsync<T>(
        string tenantId,
        string extensionId,
        T configuration) where T : class
    {
        // Validate first
        var isValid = await ValidateConfigurationAsync(extensionId, configuration);
        if (!isValid)
        {
            throw new ValidationException("Configuration validation failed");
        }

        // Extract and store secrets separately
        var secretPaths = GetSecretProperties<T>();
        foreach (var path in secretPaths)
        {
            var secretValue = GetPropertyValue(configuration, path) as string;
            if (!string.IsNullOrEmpty(secretValue) &&
                !secretValue.StartsWith("secret://"))
            {
                // Store in Key Vault
                var secretName = $"{tenantId}-{extensionId}-{path}";
                await _secretManager.SetSecretAsync(secretName, secretValue);

                // Replace with reference
                SetPropertyValue(configuration, path, $"secret://{secretName}");
            }
        }

        // Store configuration
        var configData = JsonSerializer.Serialize(configuration);
        await _configStore.SetAsync(tenantId, extensionId, configData);

        // Audit trail
        await _auditLog.LogConfigurationChangeAsync(
            tenantId, extensionId, configData);
    }
}
```

**6. Configuration Inheritance**

Extensions participate in configuration hierarchy:

```csharp
public class HierarchicalExtensionConfigurationProvider
{
    public async Task<T> GetEffectiveConfigurationAsync<T>(
        string tenantId,
        string extensionId,
        string userId = null) where T : class, new()
    {
        // Load configurations from hierarchy
        var globalConfig = await LoadGlobalExtensionConfigAsync<T>(extensionId);
        var tenantConfig = await LoadTenantExtensionConfigAsync<T>(tenantId, extensionId);
        var userConfig = userId != null
            ? await LoadUserExtensionConfigAsync<T>(tenantId, extensionId, userId)
            : null;

        // Merge with precedence: user > tenant > global
        var effectiveConfig = MergeConfigurations(globalConfig, tenantConfig, userConfig);

        return effectiveConfig;
    }
}
```

**7. Configuration Versioning and Migration**

Schema versions support migration:

```csharp
public interface IExtensionConfigurationMigration
{
    int FromVersion { get; }
    int ToVersion { get; }

    Task<object> MigrateAsync(object oldConfiguration);
}

public class FloridaPriorAuthConfigMigration_1_to_2 : IExtensionConfigurationMigration
{
    public int FromVersion => 1;
    public int ToVersion => 2;

    public Task<object> MigrateAsync(object oldConfiguration)
    {
        var oldConfig = (FloridaPriorAuthConfigV1)oldConfiguration;
        var newConfig = new FloridaPriorAuthConfigV2
        {
            ApiEndpoint = oldConfig.Endpoint,  // Renamed property
            TimeoutSeconds = oldConfig.TimeoutMs / 1000,  // Changed unit
            EnableCaching = true,  // New property with default
            ServiceCodes = oldConfig.ServiceCodes
        };

        return Task.FromResult<object>(newConfig);
    }
}
```

**8. Configuration Change Notifications**

Extensions notified of configuration changes:

```csharp
public interface IExtensionConfigurationChangeHandler
{
    Task OnConfigurationChangedAsync(
        string tenantId,
        string extensionId,
        object oldConfiguration,
        object newConfiguration);
}

public class FloridaPriorAuthExtension : IExtensionConfigurationChangeHandler
{
    public async Task OnConfigurationChangedAsync(
        string tenantId,
        string extensionId,
        object oldConfiguration,
        object newConfiguration)
    {
        var oldConfig = (FloridaPriorAuthConfig)oldConfiguration;
        var newConfig = (FloridaPriorAuthConfig)newConfiguration;

        if (oldConfig.ApiEndpoint != newConfig.ApiEndpoint)
        {
            // Reinitialize API client
            await ReinitializeApiClientAsync(newConfig.ApiEndpoint);
        }

        if (oldConfig.EnableCaching != newConfig.EnableCaching)
        {
            // Toggle caching
            _cache.Enabled = newConfig.EnableCaching;
        }
    }
}
```

