#### Phase 1: Schema Definition

**Duration**: 1 week
**Team**: Extension developers, platform architects

**Step 1.1: Define Configuration Schema**

Create JSON Schema for extension configuration:

```csharp
public interface IExtensionConfiguration
{
    /// <summary>
    /// Returns JSON Schema (draft-07) defining configuration structure
    /// </summary>
    string GetConfigurationSchema();

    /// <summary>
    /// Returns property paths that contain secrets
    /// </summary>
    IEnumerable<string> GetSecretPaths();

    /// <summary>
    /// Returns current schema version
    /// </summary>
    int GetSchemaVersion() => 1;
}

// Example implementation
public class FloridaPriorAuthExtension : IExtension, IExtensionConfiguration
{
    public string GetConfigurationSchema()
    {
        return @"
        {
          "$schema": "http://json-schema.org/draft-07/schema#",
          "$id": "https://schemas.gainwell.com/extensions/fl-prior-auth/v1",
          "title": "Florida Prior Authorization Extension Configuration",
          "description": "Configuration for Florida Medicaid prior authorization integration",
          "type": "object",
          "properties": {
            "apiEndpoint": {
              "type": "string",
              "format": "uri",
              "description": "Florida MMIS API endpoint URL",
              "examples": ["https://api.florida.gov/mmis/v1"]
            },
            "apiKey": {
              "type": "string",
              "description": "API authentication key (stored in Key Vault)",
              "minLength": 20
            },
            "timeoutSeconds": {
              "type": "integer",
              "description": "API request timeout in seconds",
              "minimum": 1,
              "maximum": 300,
              "default": 30
            },
            "maxRetries": {
              "type": "integer",
              "description": "Maximum number of retry attempts",
              "minimum": 0,
              "maximum": 5,
              "default": 3
            },
            "enableCaching": {
              "type": "boolean",
              "description": "Enable response caching",
              "default": true
            },
            "cacheDurationMinutes": {
              "type": "integer",
              "description": "Cache duration in minutes (if caching enabled)",
              "minimum": 1,
              "maximum": 1440,
              "default": 60
            },
            "serviceCodesRequiringAuth": {
              "type": "array",
              "description": "List of service codes requiring prior authorization",
              "items": {
                "type": "string",
                "pattern": "^[A-Z0-9]{4,10}$"
              },
              "minItems": 1,
              "uniqueItems": true
            },
            "notificationEmail": {
              "type": "string",
              "format": "email",
              "description": "Email for authorization failure notifications"
            }
          },
          "required": ["apiEndpoint", "apiKey", "serviceCodesRequiringAuth"],
          "additionalProperties": false
        }";
    }

    public IEnumerable<string> GetSecretPaths()
    {
        return new[] { "apiKey" };
    }

    public int GetSchemaVersion() => 1;
}
```

**Step 1.2: Create Strongly-Typed Configuration Class**

Define C# class matching schema:

```csharp
public class FloridaPriorAuthConfiguration
{
    [Required]
    [Url]
    public string ApiEndpoint { get; set; }

    [Required]
    [MinLength(20)]
    [Secret]  // Custom attribute marking this as secret
    public string ApiKey { get; set; }

    [Range(1, 300)]
    public int TimeoutSeconds { get; set; } = 30;

    [Range(0, 5)]
    public int MaxRetries { get; set; } = 3;

    public bool EnableCaching { get; set; } = true;

    [Range(1, 1440)]
    public int CacheDurationMinutes { get; set; } = 60;

    [Required]
    [MinLength(1)]
    public List<string> ServiceCodesRequiringAuth { get; set; }

    [EmailAddress]
    public string NotificationEmail { get; set; }
}
```

**Step 1.3: Register Schema with Platform**

```csharp
public class ExtensionSchemaRegistry
{
    private readonly Dictionary<string, ExtensionSchemaMetadata> _schemas = new();

    public void RegisterSchema(string extensionId, IExtensionConfiguration extension)
    {
        var schema = JsonSchema.FromText(extension.GetConfigurationSchema());
        var secretPaths = extension.GetSecretPaths().ToList();
        var version = extension.GetSchemaVersion();

        _schemas[extensionId] = new ExtensionSchemaMetadata
        {
            Schema = schema,
            SecretPaths = secretPaths,
            Version = version,
            RegisteredDate = DateTime.UtcNow
        };

        _logger.LogInformation(
            "Registered configuration schema for extension {ExtensionId}, version {Version}",
            extensionId, version);
    }
}

// Register during extension discovery
public async Task RegisterExtensionAsync(IExtension extension)
{
    if (extension is IExtensionConfiguration configurable)
    {
        _schemaRegistry.RegisterSchema(extension.Id, configurable);
    }
}
```

**Step 1.4: Generate UI Metadata from Schema**

Auto-generate admin UI forms from schema:

```csharp
public class ConfigurationUIGenerator
{
    public ConfigurationFormMetadata GenerateForm(string extensionId)
    {
        var schema = _schemaRegistry.GetSchema(extensionId);
        var form = new ConfigurationFormMetadata();

        foreach (var property in schema.Properties)
        {
            var field = new FormField
            {
                Name = property.Key,
                Label = property.Value.Title ?? ToTitleCase(property.Key),
                Description = property.Value.Description,
                Type = MapSchemaTypeToFieldType(property.Value),
                Required = schema.Required?.Contains(property.Key) ?? false,
                DefaultValue = property.Value.Default,
                Validation = ExtractValidation(property.Value)
            };

            form.Fields.Add(field);
        }

        return form;
    }
}
```

