#### Phase 2: Configuration Storage Integration

**Duration**: 2 weeks
**Team**: Backend developers, DBA, security engineers

**Step 2.1: Create Configuration Storage Schema**

```sql
CREATE TABLE ExtensionConfiguration (
    Id UNIQUEIDENTIFIER PRIMARY KEY DEFAULT NEWID(),
    TenantId NVARCHAR(50) NOT NULL,
    ExtensionId NVARCHAR(100) NOT NULL,
    ConfigurationJson NVARCHAR(MAX) NOT NULL,
    SchemaVersion INT NOT NULL DEFAULT 1,
    CreatedDate DATETIME2 NOT NULL DEFAULT GETUTCDATE(),
    CreatedBy NVARCHAR(100) NOT NULL,
    ModifiedDate DATETIME2 NOT NULL DEFAULT GETUTCDATE(),
    ModifiedBy NVARCHAR(100) NOT NULL,
    CONSTRAINT UK_ExtensionConfiguration UNIQUE (TenantId, ExtensionId),
    CONSTRAINT FK_ExtensionConfiguration_Tenant FOREIGN KEY (TenantId)
        REFERENCES Tenants(TenantId),
    CONSTRAINT CK_ExtensionConfiguration_Json CHECK (ISJSON(ConfigurationJson) = 1)
);

CREATE INDEX IX_ExtensionConfiguration_Tenant ON ExtensionConfiguration(TenantId);
CREATE INDEX IX_ExtensionConfiguration_Extension ON ExtensionConfiguration(ExtensionId);

-- Audit trail table
CREATE TABLE ExtensionConfigurationAudit (
    Id BIGINT IDENTITY PRIMARY KEY,
    TenantId NVARCHAR(50) NOT NULL,
    ExtensionId NVARCHAR(100) NOT NULL,
    ConfigurationJson NVARCHAR(MAX) NOT NULL,
    SchemaVersion INT NOT NULL,
    ChangeType NVARCHAR(20) NOT NULL,  -- Created, Updated, Deleted
    ChangedDate DATETIME2 NOT NULL DEFAULT GETUTCDATE(),
    ChangedBy NVARCHAR(100) NOT NULL,
    ChangeReason NVARCHAR(500),
    INDEX IX_ConfigurationAudit_Tenant (TenantId),
    INDEX IX_ConfigurationAudit_Extension (ExtensionId),
    INDEX IX_ConfigurationAudit_Date (ChangedDate DESC)
);

-- Trigger for audit trail
CREATE TRIGGER TR_ExtensionConfiguration_Audit
ON ExtensionConfiguration
AFTER INSERT, UPDATE, DELETE
AS
BEGIN
    SET NOCOUNT ON;

    -- Insert records
    INSERT INTO ExtensionConfigurationAudit (
        TenantId, ExtensionId, ConfigurationJson, SchemaVersion,
        ChangeType, ChangedBy
    )
    SELECT
        TenantId, ExtensionId, ConfigurationJson, SchemaVersion,
        'Created', CreatedBy
    FROM inserted
    WHERE NOT EXISTS (SELECT 1 FROM deleted);

    -- Update records
    INSERT INTO ExtensionConfigurationAudit (
        TenantId, ExtensionId, ConfigurationJson, SchemaVersion,
        ChangeType, ChangedBy
    )
    SELECT
        i.TenantId, i.ExtensionId, i.ConfigurationJson, i.SchemaVersion,
        'Updated', i.ModifiedBy
    FROM inserted i
    INNER JOIN deleted d ON i.Id = d.Id;

    -- Delete records
    INSERT INTO ExtensionConfigurationAudit (
        TenantId, ExtensionId, ConfigurationJson, SchemaVersion,
        ChangeType, ChangedBy
    )
    SELECT
        TenantId, ExtensionId, ConfigurationJson, SchemaVersion,
        'Deleted', ModifiedBy
    FROM deleted
    WHERE NOT EXISTS (SELECT 1 FROM inserted);
END;
```

**Step 2.2: Implement Configuration Provider**

```csharp
public class DatabaseExtensionConfigurationProvider : IExtensionConfigurationProvider
{
    private readonly ApplicationDbContext _dbContext;
    private readonly ISecretManager _secretManager;
    private readonly IExtensionSchemaRegistry _schemaRegistry;
    private readonly IMemoryCache _cache;
    private readonly ILogger _logger;

    public async Task<T> GetConfigurationAsync<T>(
        string tenantId,
        string extensionId,
        CancellationToken ct = default) where T : class, new()
    {
        var cacheKey = $"extconfig:{tenantId}:{extensionId}";

        // Check cache
        if (_cache.TryGetValue<T>(cacheKey, out var cached))
        {
            return cached;
        }

        // Load from database
        var configEntity = await _dbContext.ExtensionConfigurations
            .FirstOrDefaultAsync(
                ec => ec.TenantId == tenantId && ec.ExtensionId == extensionId,
                ct);

        if (configEntity == null)
        {
            _logger.LogWarning(
                "No configuration found for tenant {TenantId}, extension {ExtensionId}, using defaults",
                tenantId, extensionId);
            return new T();
        }

        // Deserialize JSON
        var config = JsonSerializer.Deserialize<T>(configEntity.ConfigurationJson);

        // Resolve secrets
        var secretPaths = _schemaRegistry.GetSecretPaths(extensionId);
        foreach (var path in secretPaths)
        {
            var secretReference = GetPropertyValue(config, path) as string;
            if (secretReference?.StartsWith("secret://") == true)
            {
                var secretName = secretReference.Substring(9);
                var secretValue = await _secretManager.GetSecretAsync(secretName, ct);
                SetPropertyValue(config, path, secretValue);
            }
        }

        // Cache for 5 minutes
        _cache.Set(cacheKey, config, TimeSpan.FromMinutes(5));

        return config;
    }

    public async Task SetConfigurationAsync<T>(
        string tenantId,
        string extensionId,
        T configuration,
        string changedBy,
        string changeReason = null,
        CancellationToken ct = default) where T : class
    {
        // Validate schema
        var validationResult = await ValidateConfigurationAsync(
            extensionId, configuration, ct);

        if (!validationResult.IsValid)
        {
            throw new ValidationException(
                $"Configuration validation failed: {string.Join(", ", validationResult.Errors)}");
        }

        // Extract and store secrets
        var configToStore = await ProcessSecretsAsync(
            tenantId, extensionId, configuration, ct);

        // Serialize
        var json = JsonSerializer.Serialize(configToStore, new JsonSerializerOptions
        {
            WriteIndented = false
        });

        // Store in database
        var existing = await _dbContext.ExtensionConfigurations
            .FirstOrDefaultAsync(
                ec => ec.TenantId == tenantId && ec.ExtensionId == extensionId,
                ct);

        if (existing != null)
        {
            existing.ConfigurationJson = json;
            existing.ModifiedDate = DateTime.UtcNow;
            existing.ModifiedBy = changedBy;
        }
        else
        {
            _dbContext.ExtensionConfigurations.Add(new ExtensionConfiguration
            {
                TenantId = tenantId,
                ExtensionId = extensionId,
                ConfigurationJson = json,
                SchemaVersion = _schemaRegistry.GetSchemaVersion(extensionId),
                CreatedBy = changedBy,
                ModifiedBy = changedBy
            });
        }

        await _dbContext.SaveChangesAsync(ct);

        // Invalidate cache
        _cache.Remove($"extconfig:{tenantId}:{extensionId}");

        // Publish change event
        await _eventPublisher.PublishAsync(new ExtensionConfigurationChangedEvent
        {
            TenantId = tenantId,
            ExtensionId = extensionId,
            ChangeReason = changeReason
        }, ct);

        _logger.LogInformation(
            "Configuration updated for tenant {TenantId}, extension {ExtensionId} by {User}",
            tenantId, extensionId, changedBy);
    }
}
```

**Step 2.3: Implement Secret Management**

```csharp
public class AzureKeyVaultSecretManager : ISecretManager
{
    private readonly SecretClient _secretClient;
    private readonly IMemoryCache _cache;

    public async Task<string> GetSecretAsync(string secretName, CancellationToken ct = default)
    {
        var cacheKey = $"secret:{secretName}";

        if (_cache.TryGetValue<string>(cacheKey, out var cached))
        {
            return cached;
        }

        var secret = await _secretClient.GetSecretAsync(secretName, cancellationToken: ct);
        var value = secret.Value.Value;

        // Cache for 1 hour
        _cache.Set(cacheKey, value, TimeSpan.FromHours(1));

        return value;
    }

    public async Task SetSecretAsync(
        string secretName,
        string secretValue,
        CancellationToken ct = default)
    {
        await _secretClient.SetSecretAsync(secretName, secretValue, ct);

        // Invalidate cache
        _cache.Remove($"secret:{secretName}");
    }
}
