```csharp
[ApiController]
[Route("api/tenants/{tenantId}/extensions/{extensionId}/configuration")]
[Authorize(Roles = "TenantAdmin,SystemAdmin")]
public class ExtensionConfigurationController : ControllerBase
{
    private readonly IExtensionConfigurationProvider _configProvider;
    private readonly IExtensionSchemaRegistry _schemaRegistry;
    private readonly ILogger<ExtensionConfigurationController> _logger;

    [HttpGet]
    public async Task<IActionResult> GetConfigurationAsync(
        string tenantId,
        string extensionId)
    {
        // Verify user has access to tenant
        if (!await _authorizationService.CanAccessTenantAsync(User, tenantId))
        {
            return Forbid();
        }

        var config = await _configProvider.GetConfigurationAsync<JsonElement>(
            tenantId, extensionId);

        return Ok(new { configuration = config });
    }

    [HttpPut]
    public async Task<IActionResult> UpdateConfigurationAsync(
        string tenantId,
        string extensionId,
        [FromBody] JsonElement configuration,
        [FromQuery] string reason = null)
    {
        if (!await _authorizationService.CanAccessTenantAsync(User, tenantId))
        {
            return Forbid();
        }

        // Validate against schema
        var validationResult = await _configProvider.ValidateConfigurationAsync(
            extensionId, configuration);

        if (!validationResult.IsValid)
        {
            return BadRequest(new
            {
                message = "Configuration validation failed",
                errors = validationResult.Errors
            });
        }

        // Update configuration
        await _configProvider.SetConfigurationAsync(
            tenantId,
            extensionId,
            configuration,
            User.Identity.Name,
            reason);

        return Ok(new { message = "Configuration updated successfully" });
    }

    [HttpGet("schema")]
    public IActionResult GetSchemaAsync(string tenantId, string extensionId)
    {
        var schema = _schemaRegistry.GetSchema(extensionId);

        if (schema == null)
        {
            return NotFound(new { message = $"Schema not found for extension {extensionId}" });
        }

        return Ok(new { schema });
    }

    [HttpPost("validate")]
    public async Task<IActionResult> ValidateConfigurationAsync(
        string tenantId,
        string extensionId,
        [FromBody] JsonElement configuration)
    {
        var validationResult = await _configProvider.ValidateConfigurationAsync(
            extensionId, configuration);

        return Ok(new
        {
            isValid = validationResult.IsValid,
            errors = validationResult.Errors
        });
    }

    [HttpGet("history")]
    public async Task<IActionResult> GetConfigurationHistoryAsync(
        string tenantId,
        string extensionId,
        [FromQuery] int page = 1,
        [FromQuery] int pageSize = 20)
    {
        var history = await _configProvider.GetConfigurationHistoryAsync(
            tenantId, extensionId, page, pageSize);

        return Ok(history);
    }
}
