```typescript
import React, { useEffect, useState } from 'react';
import { JsonSchemaForm } from '@rjsf/core';
import validator from '@rjsf/validator-ajv8';

interface ExtensionConfigProps {
  tenantId: string;
  extensionId: string;
}

export const ExtensionConfigurationEditor: React.FC<ExtensionConfigProps> = ({
  tenantId,
  extensionId
}) => {
  const [schema, setSchema] = useState(null);
  const [configuration, setConfiguration] = useState({});
  const [loading, setLoading] = useState(true);
  const [errors, setErrors] = useState([]);

  useEffect(() => {
    loadSchemaAndConfiguration();
  }, [tenantId, extensionId]);

  const loadSchemaAndConfiguration = async () => {
    try {
      // Load schema
      const schemaResponse = await fetch(
        `/api/tenants/${tenantId}/extensions/${extensionId}/configuration/schema`
      );
      const schemaData = await schemaResponse.json();
      setSchema(schemaData.schema);

      // Load current configuration
      const configResponse = await fetch(
        `/api/tenants/${tenantId}/extensions/${extensionId}/configuration`
      );
      const configData = await configResponse.json();
      setConfiguration(configData.configuration);
    } catch (error) {
      console.error('Failed to load configuration:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async ({ formData }) => {
    setErrors([]);

    // Validate before submission
    const validateResponse = await fetch(
      `/api/tenants/${tenantId}/extensions/${extensionId}/configuration/validate`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      }
    );

    const validation = await validateResponse.json();
    if (!validation.isValid) {
      setErrors(validation.errors);
      return;
    }

    // Submit configuration
    const reason = prompt('Reason for configuration change:');
    const response = await fetch(
      `/api/tenants/${tenantId}/extensions/${extensionId}/configuration?reason=${encodeURIComponent(reason)}`,
      {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      }
    );

    if (response.ok) {
      alert('Configuration updated successfully');
      loadSchemaAndConfiguration();
    } else {
      const error = await response.json();
      setErrors(error.errors || [error.message]);
    }
  };

  if (loading) return <div>Loading...</div>;

  return (
    <div className="extension-config-editor">
      <h2>Extension Configuration: {extensionId}</h2>
      {errors.length > 0 && (
        <div className="alert alert-danger">
          <strong>Validation Errors:</strong>
          <ul>
            {errors.map((error, idx) => <li key={idx}>{error}</li>)}
          </ul>
        </div>
      )}
      <JsonSchemaForm
        schema={schema}
        formData={configuration}
        validator={validator}
        onSubmit={handleSubmit}
        uiSchema={{
          'ui:submitButtonOptions': {
            submitText: 'Save Configuration'
          }
        }}
      />
    </div>
  );
};
