**Step 3.4: Add Configuration Comparison Tool**

```csharp
public class ConfigurationComparison
{
    public async Task<ConfigurationDiff> CompareConfigurationsAsync(
        long historyId1,
        long historyId2)
    {
        var config1 = await _dbContext.ExtensionConfigurationAudit
            .FindAsync(historyId1);
        var config2 = await _dbContext.ExtensionConfigurationAudit
            .FindAsync(historyId2);

        var json1 = JsonDocument.Parse(config1.ConfigurationJson);
        var json2 = JsonDocument.Parse(config2.ConfigurationJson);

        var diff = new ConfigurationDiff
        {
            FromVersion = new ConfigurationVersion
            {
                Date = config1.ChangedDate,
                ChangedBy = config1.ChangedBy
            },
            ToVersion = new ConfigurationVersion
            {
                Date = config2.ChangedDate,
                ChangedBy = config2.ChangedBy
            },
            Changes = CompareJsonObjects(json1.RootElement, json2.RootElement)
        };

        return diff;
    }

    private List<PropertyChange> CompareJsonObjects(
        JsonElement obj1,
        JsonElement obj2,
        string path = "")
    {
        var changes = new List<PropertyChange>();

        // Compare properties
        var allProps = obj1.EnumerateObject()
            .Select(p => p.Name)
            .Union(obj2.EnumerateObject().Select(p => p.Name))
            .Distinct();

        foreach (var propName in allProps)
        {
            var currentPath = string.IsNullOrEmpty(path) ? propName : $"{path}.{propName}";

            var hasProp1 = obj1.TryGetProperty(propName, out var val1);
            var hasProp2 = obj2.TryGetProperty(propName, out var val2);

            if (!hasProp1 && hasProp2)
            {
                changes.Add(new PropertyChange
                {
                    Path = currentPath,
                    ChangeType = "Added",
                    NewValue = val2.ToString()
                });
            }
            else if (hasProp1 && !hasProp2)
            {
                changes.Add(new PropertyChange
                {
                    Path = currentPath,
                    ChangeType = "Removed",
                    OldValue = val1.ToString()
                });
            }
            else if (hasProp1 && hasProp2)
            {
                if (val1.ValueKind != val2.ValueKind || val1.ToString() != val2.ToString())
                {
                    changes.Add(new PropertyChange
                    {
                        Path = currentPath,
                        ChangeType = "Modified",
                        OldValue = val1.ToString(),
                        NewValue = val2.ToString()
                    });
                }
            }
        }

        return changes;
    }
}
